# Better approach: process each connected component individually
# First, find connected components for each color

from collections import deque

def find_connected_components(grid, color, start_pos):
    """BFS to find all connected pixels of same color"""
    if grid[start_pos[0]][start_pos[1]] != color:
        return []

    rows, cols = len(grid), len(grid[0])
    visited = set()
    queue = deque([start_pos])
    component = []

    while queue:
        r, c = queue.popleft()
        if (r, c) in visited:
            continue
        visited.add((r, c))
        component.append((r, c))

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == color and (nr, nc) not in visited:
                    queue.append((nr, nc))

    return component

